create table categories (id number(10) generated by default as identity primary key, name varchar2(100) not null unique, parent_id number(10) references categories(id));
create table customers (id number(19) generated always as identity primary key, email varchar2(255 char) not null unique, full_name nvarchar2(200) not null,
  is_active number(1) default 1 not null, created_at timestamp with time zone not null, birthday date, version number(10) default 0 not null, bio clob);
comment on table customers is 'People who buy things';
comment on column customers.email is 'Login e-mail, unique';
create table products (id number(10) generated by default as identity primary key, sku char(12) not null unique, title varchar2(200) not null,
  price number(10,2) not null, weight binary_double, category_id number(10) references categories(id), image blob, uuid raw(16));
create table orders (id number(19) generated by default as identity primary key, customer_id number(19) not null references customers(id),
  placed_at timestamp not null, shipped_to_id number(19) references customers(id));
create table order_items (order_id number(19) not null references orders(id), line_no number(5) not null, product_id number(10) not null references products(id),
  quantity number(10) not null, primary key (order_id, line_no));
create table audit_log (happened_at timestamp not null, action varchar2(400) not null);
create view order_summary as select o.id, c.email from orders o join customers c on c.id = o.customer_id;
exit
